package protocol

import (
	"encoding/json"
	"fmt"
)

// ResourceKey identifies one of the four shared resources.
type ResourceKey string

const (
	ResourceWater  ResourceKey = "water"
	ResourceOxygen ResourceKey = "oxygen"
	ResourceEnergy ResourceKey = "energy"
	ResourceFood   ResourceKey = "food"
)

// SolarResource identifies a resource generated by a solar storm.
type SolarResource string

const (
	SolarWater  SolarResource = "water"
	SolarOxygen SolarResource = "oxygen"
	SolarEnergy SolarResource = "energy"
)

// ResourceAmounts is one value per resource.
type ResourceAmounts struct {
	Water  float64 `json:"water"`
	Oxygen float64 `json:"oxygen"`
	Energy float64 `json:"energy"`
	Food   float64 `json:"food"`
}

// ResourcePool is the spendable part of a resource.
type ResourcePool struct {
	Current float64 `json:"current"`
	Max     float64 `json:"max"`
}

// ResourceStash is the passively generated part of a resource.
type ResourceStash struct {
	Current float64 `json:"current"`
	Max     float64 `json:"max"`
	GPS     float64 `json:"gps"`
}

// ResourceState is one resource in match.state and match.frame.
type ResourceState struct {
	Pool  ResourcePool  `json:"pool"`
	Stash ResourceStash `json:"stash"`
	CPS   float64       `json:"cps"`
}

// Resources holds all four resource states.
type Resources struct {
	Water  ResourceState `json:"water"`
	Oxygen ResourceState `json:"oxygen"`
	Energy ResourceState `json:"energy"`
	Food   ResourceState `json:"food"`
}

// GridSize is the playfield size in cells.
type GridSize struct {
	Width  int `json:"width"`
	Height int `json:"height"`
}

// Facing is a player's cardinal direction.
type Facing string

const (
	FacingNorth Facing = "north"
	FacingEast  Facing = "east"
	FacingSouth Facing = "south"
	FacingWest  Facing = "west"
)

// Phase is a match lifecycle phase. match.ended is terminal.
type Phase string

const (
	PhaseLobby     Phase = "lobby"
	PhaseCountdown Phase = "countdown"
	PhasePlaying   Phase = "playing"
)

// PlayerState is one player in match.state and match.frame.
type PlayerState struct {
	ID           string  `json:"id"`
	Slot         int     `json:"slot"`
	Name         string  `json:"name"`
	Facing       Facing  `json:"facing"`
	X            float64 `json:"x"`
	Y            float64 `json:"y"`
	VX           float64 `json:"vx"`
	VY           float64 `json:"vy"`
	LastInputSeq int64   `json:"lastInputSeq"`
}

// ConstructionKind is the kind of a base construction.
type ConstructionKind string

const (
	ConstructionBaseTile ConstructionKind = "base_tile"
	ConstructionStash    ConstructionKind = "stash"
)

// Construction is one base cell.
type Construction struct {
	ID    string           `json:"id"`
	Kind  ConstructionKind `json:"kind"`
	CellX int              `json:"cellX"`
	CellY int              `json:"cellY"`
}

// InvestigationCell is one goal cell.
type InvestigationCell struct {
	CellX int `json:"cellX"`
	CellY int `json:"cellY"`
}

// MatchState is the full match state returned on join and phase changes.
type MatchState struct {
	MatchID       string              `json:"matchId"`
	Schema        int                 `json:"schema"`
	Tick          int64               `json:"tick"`
	ServerTimeMs  int64               `json:"serverTimeMs"`
	Phase         Phase               `json:"phase"`
	PhaseEndsAtMs int64               `json:"phaseEndsAtMs"`
	HostID        string              `json:"hostId"`
	Grid          GridSize            `json:"grid"`
	BaseCellCount int                 `json:"baseCellCount"`
	TeamSize      int                 `json:"teamSize"`
	Players       []PlayerState       `json:"players"`
	Constructions []Construction      `json:"constructions"`
	Investigation []InvestigationCell `json:"investigation"`
	Resources     Resources           `json:"resources"`
	Phenomenon    ActivePhenomenon    `json:"phenomenon"`
}

// MarshalJSON emits empty arrays instead of null for required list fields.
func (m MatchState) MarshalJSON() ([]byte, error) {
	type wire MatchState
	value := wire(m)
	if value.Players == nil {
		value.Players = []PlayerState{}
	}
	if value.Constructions == nil {
		value.Constructions = []Construction{}
	}
	if value.Investigation == nil {
		value.Investigation = []InvestigationCell{}
	}
	return json.Marshal(value)
}

// MatchFrame is the lossy state frame, broadcast at the configured frame rate.
type MatchFrame struct {
	MatchID       string           `json:"matchId"`
	Tick          int64            `json:"tick"`
	ServerTimeMs  int64            `json:"serverTimeMs"`
	HostID        string           `json:"hostId"`
	BaseCellCount int              `json:"baseCellCount"`
	TeamSize      int              `json:"teamSize"`
	Players       []PlayerState    `json:"players"`
	Resources     Resources        `json:"resources"`
	Phenomenon    ActivePhenomenon `json:"phenomenon"`
}

// MarshalJSON emits an empty array instead of null for the required player list.
func (m MatchFrame) MarshalJSON() ([]byte, error) {
	type wire MatchFrame
	value := wire(m)
	if value.Players == nil {
		value.Players = []PlayerState{}
	}
	return json.Marshal(value)
}

// MatchBuild is the reliable construction event.
type MatchBuild struct {
	MatchID      string       `json:"matchId"`
	Construction Construction `json:"construction"`
	Resources    Resources    `json:"resources"`
}

// MatchPhenomenonAction is the transition carried by match.phenomenon.
type MatchPhenomenonAction string

const (
	PhenomenonActionStarted  MatchPhenomenonAction = "started"
	PhenomenonActionResolved MatchPhenomenonAction = "resolved"
	PhenomenonActionInstant  MatchPhenomenonAction = "instant"
)

// MatchPhenomenon is the reliable phenomenon transition event.
type MatchPhenomenon struct {
	MatchID    string                `json:"matchId"`
	Action     MatchPhenomenonAction `json:"action"`
	Phenomenon Phenomenon            `json:"phenomenon"`
}

// MatchOutcome is the shared result of a match.
type MatchOutcome string

const (
	OutcomeWin       MatchOutcome = "win"
	OutcomeLoss      MatchOutcome = "loss"
	OutcomeAbandoned MatchOutcome = "abandoned"
)

// MatchEndReason is the reason a match ended.
type MatchEndReason string

const (
	ReasonAllInvestigated  MatchEndReason = "all_investigated"
	ReasonResourceDepleted MatchEndReason = "resource_depleted"
	ReasonAbandoned        MatchEndReason = "abandoned"
)

// MatchStats summarizes a finished match.
type MatchStats struct {
	ElapsedMs            int64           `json:"elapsedMs"`
	BaseCells            int             `json:"baseCells"`
	InvestigationCovered int             `json:"investigationCovered"`
	InvestigationTotal   int             `json:"investigationTotal"`
	Remaining            ResourceAmounts `json:"remaining"`
	DepletedResource     ResourceKey     `json:"depletedResource,omitempty"`
}

// MatchEnded is the terminal match result.
type MatchEnded struct {
	MatchID   string         `json:"matchId"`
	EndedAtMs int64          `json:"endedAtMs"`
	Outcome   MatchOutcome   `json:"outcome"`
	Reason    MatchEndReason `json:"reason"`
	Stats     MatchStats     `json:"stats"`
}

// BuildCost is the pool cost of one base tile.
type BuildCost struct {
	Water  float64 `json:"water"`
	Oxygen float64 `json:"oxygen"`
	Energy float64 `json:"energy"`
	Food   float64 `json:"food"`
}

// Rules are the gameplay constants published in the welcome.
type Rules struct {
	Grid                  GridSize  `json:"grid"`
	InvestigationCount    int       `json:"investigationCount"`
	BuildCost             BuildCost `json:"buildCost"`
	PlayerSpeed           float64   `json:"playerSpeed"`
	PhenomenonRollSeconds float64   `json:"phenomenonRollSeconds"`
}

// Limits are the connection and match limits published in the welcome.
type Limits struct {
	MaxMessageBytes    int `json:"maxMessageBytes"`
	MaxPlayersPerMatch int `json:"maxPlayersPerMatch"`
	MaxNicknameLength  int `json:"maxNicknameLength"`
	MaxMatches         int `json:"maxMatches"`
}

// Welcome is the first server event.
type Welcome struct {
	PlayerID        string  `json:"playerId"`
	ProtocolVersion int     `json:"protocolVersion"`
	ServerTimeMs    int64   `json:"serverTimeMs"`
	TickRate        float64 `json:"tickRate"`
	FrameRate       float64 `json:"frameRate"`
	Limits          Limits  `json:"limits"`
	Rules           Rules   `json:"rules"`
}

// ErrorPayload carries optional human-readable error details.
type ErrorPayload struct {
	Message string        `json:"message,omitempty"`
	Missing []ResourceKey `json:"missing,omitempty"`
}

// PongPayload answers a ping.
type PongPayload struct {
	ClientTimeMs *float64 `json:"clientTimeMs,omitempty"`
	ServerTimeMs int64    `json:"serverTimeMs"`
	Tick         int64    `json:"tick"`
}

// HelloResult confirms the identified player.
type HelloResult struct {
	PlayerID string `json:"playerId"`
	Nickname string `json:"nickname"`
}

// MatchJoinResult returns the match id and its full state.
type MatchJoinResult struct {
	MatchID string     `json:"matchId"`
	State   MatchState `json:"state"`
}

// OKPayload is the payload of successful control responses.
type OKPayload struct{}

// MarshalJSON implements json.Marshaler.
func (OKPayload) MarshalJSON() ([]byte, error) {
	return []byte(`{"ok":true}`), nil
}

// UnmarshalJSON implements json.Unmarshaler.
func (*OKPayload) UnmarshalJSON(data []byte) error {
	var wire struct {
		OK bool `json:"ok"`
	}
	if err := json.Unmarshal(data, &wire); err != nil {
		return err
	}
	if !wire.OK {
		return fmt.Errorf("protocol: ok must be true")
	}
	return nil
}

// StashCollectResult reports the resources moved and lost.
type StashCollectResult struct {
	Collected ResourceAmounts `json:"collected"`
	Lost      ResourceAmounts `json:"lost"`
	Resources Resources       `json:"resources"`
}

// BaseBuildResult returns the new construction and updated resources.
type BaseBuildResult struct {
	Construction Construction `json:"construction"`
	Resources    Resources    `json:"resources"`
}

// PhenomenonFixResult returns the cleared phenomenon and updated resources.
type PhenomenonFixResult struct {
	Phenomenon ActivePhenomenon `json:"phenomenon"`
	Resources  Resources        `json:"resources"`
}
